import{c as t,Q as a,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"Let's Verify Step by Step","description":"","frontmatter":{"url":"https://arxiv.org/abs/2305.20050","title":"Let's Verify Step by Step","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2305.2005,"authors":["Hunter Lightman","Vineet Kosaraju","Yura Burda","Harri Edwards","Bowen Baker","Teddy Lee","Jan Leike","John Schulman","Ilya Sutskever","Karl Cobbe"],"pdf_path":"pdfs/2305.20050.pdf","published_date":"2023-05-31T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2023-05-31-lets-verify-step-by-step-process-reward-2305-20050.md","filePath":"research/papers/2023-05-31-lets-verify-step-by-step-process-reward-2305-20050.md","lastUpdated":1785909234000}`),s={name:"research/papers/2023-05-31-lets-verify-step-by-step-process-reward-2305-20050.md"};function n(o,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="let-s-verify-step-by-step" tabindex="-1">Let&#39;s Verify Step by Step <a class="header-anchor" href="#let-s-verify-step-by-step" aria-label="Permalink to &quot;Let&#39;s Verify Step by Step&quot;">​</a></h1><p><strong>Authors:</strong> Hunter Lightman, Vineet Kosaraju, Yura Burda, Harri Edwards, Bowen Baker, Teddy Lee, Jan Leike, John Schulman, Ilya Sutskever, Karl Cobbe <strong>Year:</strong> 2023 <strong>Submitted:</strong> May 31, 2023 <strong>Venue:</strong> ICLR 2024 (OpenAI) <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2305.20050" target="_blank" rel="noreferrer">https://arxiv.org/abs/2305.20050</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>In recent years, large language models have greatly improved in their ability to perform complex multi-step reasoning. However, even state-of-the-art models still regularly produce logical mistakes. To train more reliable models, we can turn either to outcome supervision, which provides feedback for a final result, or process supervision, which provides feedback for each intermediate reasoning step. Given the importance of training reliable multi-step reasoning models, we conduct a careful study of these two methods. We find that process supervision significantly outperforms outcome supervision for training models to solve problems from the challenging MATH dataset. Our process-supervised reward model (PRM) achieves 78% on a representative subset of MATH problems. Additionally, we show that active learning significantly improves the efficacy of process supervision. To support related research, we release PRM800K, the complete dataset of 800,000 step-level human feedback labels used to train our best reward model.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Process supervision vs. outcome supervision</strong>: Establishes empirically that providing step-level feedback during training significantly outperforms final-answer-only feedback for complex multi-step mathematical reasoning.</li><li><strong>Process Reward Model (PRM)</strong>: Introduces the PRM paradigm — a reward model trained to score the correctness likelihood of each individual intermediate reasoning step, enabling fine-grained verification of chain-of-thought reasoning.</li><li><strong>78% accuracy on MATH</strong>: The best PRM achieves 78% on a representative subset of MATH benchmark problems, setting a strong baseline for PRM-based verification.</li><li><strong>Active learning for process supervision</strong>: Shows that active learning (selecting data points where the model is most uncertain) substantially improves sample efficiency and final performance of process supervision compared to random data collection.</li><li><strong>PRM800K dataset release</strong>: Publishes 800,000 step-level human feedback labels — the dataset used to train all reward models — enabling reproducible PRM research and downstream use in inference-time scaling pipelines.</li><li><strong>Foundation for best-of-N inference</strong>: Provides the empirical and methodological basis for PRM-based best-of-N selection, which became a standard component in test-time compute scaling systems (including Snell et al. 2024, DeepSeek-R1, and o1).</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The paper compares two supervision paradigms for training reward models on the MATH benchmark. <strong>Outcome supervision (ORM)</strong> trains a reward model to predict whether a complete solution reaches the correct final answer. The model receives a binary signal only at the end of each generation. This approach is inexpensive to label but provides sparse feedback — the model cannot distinguish between a correct intermediate step that leads to an incorrect final step and a fundamentally flawed reasoning chain.</p><p><strong>Process supervision (PRM)</strong> trains a reward model to predict, at each intermediate reasoning step, whether that step is correct given the problem statement and prior steps. Human annotators label each step as positive, negative, or neutral. This provides dense, intermediate feedback, allowing the reward model to identify exactly where a reasoning chain goes wrong. At inference time, the PRM scores each step of a candidate solution, and the overall solution score is typically the minimum step score (the weakest link). This PRM score is then used to select the best candidate from a set of N generated solutions (best-of-N selection).</p><p><strong>Active learning</strong> is used to improve labeling efficiency. Rather than randomly sampling problems and solutions for annotation, the authors identify problems where the model&#39;s predicted step-level correctness is most uncertain — prioritizing annotations that maximally improve PRM calibration. This substantially reduces the number of human labels required to achieve a given level of PRM accuracy, making process supervision more practical at scale.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li><strong>PRM vs. ORM on MATH</strong>: The best PRM reaches 78% accuracy on a representative MATH subset under best-of-N selection; the best ORM trained on equivalent data reaches lower accuracy.</li><li><strong>Scaling best-of-N with PRM</strong>: Performance improves consistently as N increases (more candidates generated), with PRM-based selection significantly outperforming random selection and ORM-based selection.</li><li><strong>Active learning gain</strong>: Active learning reduces the required annotation budget by approximately 2x compared to random sampling to reach equivalent PRM accuracy.</li><li><strong>Step-level feedback localizes errors</strong>: Qualitative analysis shows that PRMs correctly identify the specific step where a reasoning chain goes wrong in the majority of failure cases, confirming that step-level labels carry signal beyond final-answer supervision.</li><li><strong>PRM800K quality</strong>: The released dataset spans 800,000 step-level labels across 75,000 solutions to 12,000 MATH problems, covering all difficulty levels and mathematical subfields.</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Human annotation of step-level correctness is expensive and does not scale trivially to domains without well-defined step boundaries (e.g., open-ended writing, multi-document reasoning).</li><li>PRM training requires agreement between annotators on what constitutes a &quot;step&quot; — ambiguous in domains outside structured mathematical reasoning.</li><li>The PRM is trained on human-written solutions from GPT-4; generalization to solutions from different model families may require retraining or domain adaptation.</li><li>Best-of-N selection with PRM is a parallel scaling strategy — it generates N solutions independently. Combining PRM with sequential search (MCTS, beam search) is identified as future work.</li><li>The benchmark is limited to the MATH dataset; generalization to other reasoning domains (science, coding, logical deduction) requires additional study.</li><li>Future directions include automated step-level labeling, PRM training from RL feedback (rather than human labels), and integration with sequential search algorithms.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>This paper is the <strong>foundational work for process reward models</strong>, which became a core component in virtually all subsequent test-time compute scaling systems. For practitioners, the key insight is that verifying reasoning at the step level — rather than only at the final answer — provides substantially better signal for selecting among candidate solutions at inference time. The PRM800K dataset release enabled the community to train and evaluate PRMs without the prohibitive cost of collecting step-level labels from scratch. The best-of-N selection paradigm described here is directly implemented in o1, DeepSeek-R1, and the Snell et al. compute-optimal scaling framework. Any practitioner building a reasoning pipeline that generates multiple candidates and selects among them is applying the core methodology of this paper. The active learning results also suggest a practical path to reducing annotation costs when fine-tuning PRMs for new domains.</p>',22)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
